module troublemakers (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [7:0] k,\n    input wire [7:0] n,\n    output reg [7:0] result,\n    output reg done\n);\n    \n    localparam [2:0] IDLE      = 3'd0;\n    localparam [2:0] COMPUTE   = 3'd1;\n    localparam [2:0] CHECK     = 3'd2;\n    localparam [2:0] INCREMENT = 3'd3;\n    localparam [2:0] DONE_ST   = 3'd4;\n    \n    reg [2:0] state;\n    reg [7:0] i;\n    reg [15:0] F_prev_prev, F_prev, F_curr;\n    reg [7:0] count;\n    reg is_wonderful;\n    \n    // Lookup table for wonderful numbers\n    always @(*) begin\n        case (F_curr)\n            16'd121, 16'd143, 16'd1147, 16'd1457: is_wonderful = 1'b1;\n            default: is_wonderful = 1'b0;\n        endcase\n    end\n    \n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            i <= 8'd0;\n            F_prev_prev <= 16'd0;\n            F_prev <= 16'd0;\n            F_curr <= 16'd0;\n            count <= 8'd0;\n            done <= 1'b0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        i <= 8'd1;\n                        count <= 8'd0;\n                        F_prev_prev <= 16'd0;\n                        F_prev <= 16'd0;\n                        state <= COMPUTE;\n                    end\n                end\n                \n                COMPUTE: begin\n                    if (i == 8'd1) begin\n                        F_curr <= 16'd42;\n                    end else if (i == 8'd2) begin\n                        F_curr <= (11 * k) + 16'd77;\n                    end else begin\n                        F_curr <= (F_prev << 1) - F_prev_prev + (10 * k);\n                    end\n                    state <= CHECK;\n                end\n                \n                CHECK: begin\n                    if (is_wonderful) begin\n                        count <= count + 8'd1;\n                    end\n                    state <= INCREMENT;\n                end\n                \n                INCREMENT: begin\n                    F_prev_prev <= F_prev;\n                    F_prev <= F_curr;\n                    i <= i + 8'd1;\n                    if (i >= n) begin\n                        state <= DONE_ST;\n                    end else begin\n                        state <= COMPUTE;\n                    end\n                end\n                \n                DONE_ST: begin\n                    result <= count;\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule